    const prizes=seconds.map((duration,i)=>{
      const integrals=Math.max(25,Math.floor(Math.max(1,s.cps)*duration*(.9+Math.random()*.2)));
      return {id:i,weight:weights[i],integrals,...(slots.includes(i)?candidate(integrals,s):{})};
    });
